import{c as t,Q as o,j as d,m as a}from"./chunks/framework.g_l1frA7.js";const h=JSON.parse('{"title":"Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"developers/frontend.md","filePath":"developers/frontend.md","lastUpdated":null}'),r={name:"developers/frontend.md"};function c(s,e,n,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h1><p>React 18 + TypeScript + Vite, TanStack Query, React Router, and a server-served SPA. No Tauri shim.</p><h2 id="entry" tabindex="-1">Entry <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Entry&quot;">​</a></h2><p><code>ui/index.html</code> bootstraps to <code>src/main.tsx</code> → <code>src/App.tsx</code>. The HTML defaults to <code>data-theme=&quot;dark&quot; data-density=&quot;cozy&quot;</code> so tokens exist before React mounts and auth/setup screens have correct inputs even before <code>ThemeProvider</code>.</p><p>Relevant <code>&lt;meta&gt;</code>:</p><ul><li><code>theme-color: #0A0F02</code> (lime-adjacent brand)</li><li><code>viewport-fit=cover</code> for PWA</li></ul><h2 id="data-layer" tabindex="-1">Data layer <a class="header-anchor" href="#data-layer" aria-label="Permalink to &quot;Data layer&quot;">​</a></h2><ul><li><code>api/openapi.ts</code> — generated types.</li><li><code>api/openapiClient.ts</code> — <code>createClient</code> from <code>openapi-fetch</code>, envelope unwrapping, 401 → auth gate.</li><li><code>api/hooks/</code> — thin <code>useQuery</code>/<code>useMutation</code> wrappers, key factory in <code>_factory.ts</code>.</li><li><code>api/prefetch.ts</code> — warms summary queries on link hover/focus (<code>prefetchRoute</code>).</li><li><code>api/invalidation.ts</code> — maps mutation → query invalidation.</li><li><code>pwa/persist.ts</code> — seven-day IndexedDB persist for queries (<code>@tanstack/query-async-storage-persister</code> + <code>idb-keyval</code>), encrypted when the PWA has a secure context.</li><li><code>utils/runtime.ts</code> — <code>isBackendAvailable()</code> guard.</li></ul><h2 id="components-screens" tabindex="-1">Components &amp; screens <a class="header-anchor" href="#components-screens" aria-label="Permalink to &quot;Components &amp; screens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>components/Drawer.tsx</code></td><td>Slide-in panel primitive with focus lock</td></tr><tr><td><code>components/CommandPalette.tsx</code></td><td>⌘K palette</td></tr><tr><td><code>components/copilot/</code></td><td>Streamdown renderers for rich Copilot cards</td></tr><tr><td><code>components/mobile/*</code></td><td>Bottom nav + responsive shells</td></tr><tr><td><code>screens/</code></td><td>One file per route (see <code>routes.ts</code>)</td></tr><tr><td><code>routes.ts</code></td><td>Canonical <code>APP_ROUTES</code>; mirrored in Rust <code>routes.rs</code></td></tr></tbody></table><p>Routes and backend link generation are kept honest by <code>routes.test.ts</code> — the test enforces that <code>APP_ROUTES</code> matches <code>&lt;Route&gt;</code> elements and Rust <code>APP_ROUTES</code>.</p><h2 id="styling" tabindex="-1">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to &quot;Styling&quot;">​</a></h2><p>See <a href="/FinSight/developers/css">CSS &amp; Design</a>. Key points:</p><ul><li>Tokens in <code>styles/tokens.css</code>, utilities in <code>styles/app.css</code>.</li><li>Money figures use class <code>&quot;money&quot;</code> for privacy blur.</li><li>Motion respects <code>prefers-reduced-motion</code>.</li></ul><p>Next: <a href="/FinSight/developers/crates">Rust Crates</a>.</p>',15)])])}const m=t(r,[["render",c]]);export{h as __pageData,m as default};
